#include <stdlib.h>

#define MOD 1000000007LL

static long long mod_pow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    long long N;
    if (scanf("%lld", &N) != 1) return 0;

    if (N == 1) {
        /* No machine exists, all squares are already black "for the first time" before any operation. */
        printf("0\n");
        return 0;
    }

    long long M = N - 1; /* number of machines / edges */

    /* factorials up to M */
    long long *fact = (long long *)malloc((M + 1) * sizeof(long long));
    long long *invfact = (long long *)malloc((M + 1) * sizeof(long long));
    if (!fact || !invfact) return 0;

    fact[0] = 1;
    for (long long i = 1; i <= M; ++i) fact[i] = fact[i - 1] * i % MOD;

    invfact[M] = mod_pow(fact[M], MOD - 2);
    for (long long i = M; i >= 1; --i) invfact[i - 1] = invfact[i] * i % MOD;

    /*
      Let edges be 1..M between consecutive squares.
      After operating a set S of edges, all N squares are black iff every vertex is incident to some chosen edge.
      On a path, the number of k-edge subsets covering all vertices equals:
        g(k) = C(k-1, N-k-1), for ceil(N/2) <= k <= N-1
      (choose lengths of zero-runs between chosen edges).

      For a permutation, score = smallest t such that first t chosen edges cover all vertices.
      Summing over all permutations:
        answer = sum_{t=1..M} t * (#permutations whose first cover occurs at t)

      Equivalent:
        answer = sum_{covered subsets S} |S|! * (M-|S|)! * [S covers all vertices and no proper subset of S appearing earlier matters]
      More directly, by linearity on stopping time:
        #permutations with score <= t is based on first t-set covering,
        yielding:
        answer = sum_{k} k * g(k) * k! * (M-k)! 
               - sum_{k} ... 
      Simplifying with standard identity for stopping time:
        answer = sum_{k=0}^{M-1} (M! - #permutations whose first k edges already cover all vertices)
               = sum_{k=0}^{M-1} (M! - g(k) * k! * (M-k)!)
        where g(k)=0 if impossible.
        Thus:
        answer = M * M! - sum_k g(k) * k! * (M-k)!.

      Since g(k)=C(k-1, N-k-1),
        g(k) * k! * (M-k)!
        = (k-1)! / (N-k-1)! / (2k-N)! * k! * (N-1-k)!
        = k! * (k-1)! * (N-1-k)! / ((N-k-1)! * (2k-N)!)
        = k! * (k-1)! / (2k-N)!   because (N-1-k)! = (N-k-1)!
      so term = k! * (k-1)! / (2k-N)!.

      We'll compute directly using combinations:
        term = C(k-1, N-k-1) * k! * (M-k)! mod MOD
      for k from ceil(N/2) to M.
      Then answer = M*M! - sum_{k=0}^{M-1} term.
      Note k=M always covers all vertices, but the stopping-time formula sums only to M-1.
    */

    long long total = M % MOD * fact[M] % MOD;
    long long sub = 0;

    long long start = (N + 1) / 2; /* ceil(N/2) */
    for (long long k = start; k <= M - 1; ++k) {
        long long choose = fact[k - 1] * invfact[N - k - 1] % MOD * invfact[2 * k - N] % MOD;
        long long term = choose * fact[k] % MOD * fact[M - k] % MOD;
        sub += term;
        if (sub >= MOD) sub -= MOD;
    }

    long long ans = (total - sub) % MOD;
    if (ans < 0) ans += MOD;

    printf("%lld\n", ans);

    free(fact);
    free(invfact);
    return 0;
}

