public class Main {
    static final long MOD = 1_000_000_007;
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        if (N == 1) { System.out.println(0); return; }
        int n = N - 1; // number of machines
        long[] fact = new long[n + 1], inv_fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = fact[i-1] * i % MOD;
        inv_fact[n] = modpow(fact[n], MOD-2, MOD);
        for (int i = n-1; i >= 0; i--) inv_fact[i] = inv_fact[i+1] * (i+1) % MOD;
        long ans = 0;
        for (int k = 0; k <= n - 1; k++) {
            long total = comb(n, k, fact, inv_fact);
            long hk = comb(k-1, n-k, fact, inv_fact); // C(k-1, N-1-k)
            long gk = (total - hk % MOD + MOD) % MOD;
            ans = (ans + fact[k] % MOD * fact[n-k] % MOD * gk) % MOD;
        }
        System.out.println(ans);
    }
    static long comb(int n, int r, long[] fact, long[] inv_fact) {
        if (r < 0 || r > n || n < 0) return 0;
        return fact[n] * inv_fact[r] % MOD * inv_fact[n-r] % MOD;
    }
    static long modpow(long base, long exp, long mod) {
        long result = 1; base %= mod;
        while (exp > 0) { if ((exp&1)==1) result = result*base%mod; base=base*base%mod; exp>>=1; }
        return result;
    }
}

