import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();

        // Let edges be the N-1 machines on a path of N vertices.
        // For a permutation, the score is the first time all vertices are covered.
        //
        // Sum of scores over all permutations:
        //   S = sum_{k=1}^{N-1} P(score >= k)
        // over all permutations, equivalently
        //   S = sum_{k=1}^{N-1} (# of permutations whose first k-1 edges do NOT cover all vertices)
        //
        // For fixed t = k-1, choose the first t edges as an ordered list.
        // Count ordered t-tuples of distinct edges whose set does not cover all vertices,
        // then multiply by (N-1-t)! for the remaining suffix.
        //
        // On a path, a set of t edges covers all N vertices iff:
        // - edge 1 is chosen,
        // - edge N-1 is chosen,
        // - and there are no two consecutive unchosen edges.
        //
        // Let m = N-1 (#edges). Number of t-edge subsets that cover all vertices equals
        // number of size z = m-t unchosen-edge subsets with:
        //   - no endpoints chosen among {1,m}
        //   - no consecutive chosen
        // This is C(t-1, m-t) = C(t-1, N-1-t), valid when 2t >= N.
        //
        // Therefore for each t:
        //   badSubsets = C(m, t) - C(t-1, m-t)
        // where the second term is 0 if invalid.
        //
        // Contribution to S from this t:
        //   badSubsets * t! * (m-t)! = badSubsets * m! / C(m,t)
        // but simpler:
        //   C(m,t)*t!*(m-t)! = m!
        //   C(t-1,m-t)*t!*(m-t)! = (t-1)! * t! / (2t-m-1)! * (m-t)!? easier via factorials.
        //
        // So:
        // contribution(t) = m! - C(t-1, m-t) * t! * (m-t)!
        // and second term simplifies to:
        //   (t-1)! / (2t-m-1)! * t!
        // since C(t-1,m-t) = (t-1)! / ((m-t)! (2t-m-1)!)
        //
        // Total:
        //   S = sum_{t=0}^{m-1} contribution(t)
        // because k=1..m corresponds to t=k-1 = 0..m-1.
        // For t=0, cover impossible, contribution = m!.
        //
        // Hence:
        //   S = m * m! - sum_{t: 2t>=N} C(t-1, m-t) * t! * (m-t)!
        //
        // Compute directly with factorials/inverses.

        int m = N - 1;
        long[] fact = new long[Math.max(1, m) + 1];
        long[] invFact = new long[Math.max(1, m) + 1];
        fact[0] = 1;
        for (int i = 1; i <= m; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[m] = modPow(fact[m], MOD - 2);
        for (int i = m; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;

        long ans = (long) m * fact[m] % MOD;

        for (int t = 0; t <= m - 1; t++) {
            int z = m - t;
            // cover-count valid iff endpoints excluded and no adjacent among z unchosen edges:
            // number = C(t-1, z), requiring t-1 >= z >= 0
            if (t - 1 >= z && z >= 0) {
                long coverSubsets = comb(t - 1, z, fact, invFact);
                long ways = coverSubsets * fact[t] % MOD * fact[z] % MOD;
                ans -= ways;
                if (ans < 0) ans += MOD;
            }
        }

        System.out.println(ans % MOD);
    }

    static long comb(int n, int r, long[] fact, long[] invFact) {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

