#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N;
    cin >> N;

    // There are M = N-1 machines (edges of a path with N vertices).
    // For a permutation, let score be the first time all N squares become black.
    //
    // After operating some set S of edges, all squares are black iff every vertex
    // is incident to at least one chosen edge, i.e. S is an edge cover of the path.
    //
    // For a permutation p, score = min k such that first k edges form an edge cover.
    //
    // Sum of scores over all permutations:
    //   sum_p score(p) = sum_{k>=1} #{ p : score(p) >= k }
    //                  = sum_{k>=1} #{ p : first k-1 edges do NOT form an edge cover }.
    //
    // For fixed t = k-1, number of permutations whose first t edges are some
    // non-cover subset = (# non-cover subsets of size t) * t! * (M-t)!.
    //
    // So answer = sum_{t=0}^{M} A_t * t! * (M-t)!,
    // where A_t = number of size-t subsets of edges of the path that are NOT edge covers.
    //
    // Let C_t = number of size-t subsets that ARE edge covers.
    // Then A_t = binom(M,t) - C_t, hence
    //   A_t * t! * (M-t)! = M! - C_t * t! * (M-t)!.
    //
    // Therefore:
    //   answer = (M+1) * M! - sum_t C_t * t! * (M-t)!.
    //
    // Now count edge covers of a path.
    // A subset S of edges is an edge cover iff:
    //   - edge 1 is chosen (to cover vertex 1),
    //   - edge M is chosen (to cover vertex N),
    //   - there are no two consecutive unchosen edges
    //     (otherwise the middle vertex between them is uncovered).
    //
    // Equivalently, the 0/1 string of length M has:
    //   first and last bits = 1, and no "00".
    //
    // If exactly t edges are chosen, let z = M - t be unchosen.
    // Since ends are 1, the z zeros must be placed among the internal positions
    // 2..M-1, with no adjacency. Number of ways:
    //   C_t = binom(t-1, M-t), valid when M-t <= t-1.
    //
    // So we need:
    //   sum_t binom(t-1, M-t) * t! * (M-t)!
    // Let z = M-t. Then t = M-z:
    //   binom(M-z-1, z) * (M-z)! * z!
    // = (M-z-1)! / (z! (M-2z-1)!) * (M-z)! * z!
    // = (M-z)! * (M-z-1)! / (M-2z-1)!.
    //
    // Range: z = 0..floor((M-1)/2), except for M=0 separately.
    //
    // Since M = N-1:
    // answer = N * (N-1)! - sum_{z=0}^{floor((N-2)/2)}
    //          (N-1-z)! * (N-2-z)! / (N-2z-2)!.

    if (N == 1) {
        // No machine, score is 0 for the only permutation (empty one).
        cout << 0 << '\n';
        return 0;
    }

    long long M = N - 1;

    vector<long long> fact(N + 1), invfact(N + 1);
    fact[0] = 1;
    for (long long i = 1; i <= N; ++i) fact[i] = fact[i - 1] * i % MOD;
    invfact[N] = modpow(fact[N], MOD - 2);
    for (long long i = N; i >= 1; --i) invfact[i - 1] = invfact[i] * i % MOD;

    long long ans = N % MOD * fact[M] % MOD; // (M+1)*M! = N*(N-1)!

    long long cover_sum = 0;
    for (long long z = 0; z <= (M - 1) / 2; ++z) {
        // term = (M-z)! * (M-z-1)! / (M-2z-1)!
        long long term = fact[M - z] * fact[M - z - 1] % MOD * invfact[M - 2 * z - 1] % MOD;
        cover_sum += term;
        if (cover_sum >= MOD) cover_sum -= MOD;
    }

    ans = (ans - cover_sum) % MOD;
    if (ans < 0) ans += MOD;

    cout << ans << '\n';
    return 0;
}
